mapper.select:
SELECT
  count(*) cnt
FROM
  ttokssaemdb.timetable_period
WHERE
  useyn = 'Y'
  AND branchid = #{branchid}
  AND startdate  <=  #{enddate}
  AND enddate  >=  #{startdate}

    AND periodid  <>  ${periodid}

mapper.delete:
DELETE FROM ttokssaemdb.timetable_period
WHERE
  periodid = ${periodid}
  AND branchid = #{branchid}
